"""Build chapter 08 with explicitly fictional frequency examples."""
from pathlib import Path
from html import escape
import json,re
ROOT=Path(__file__).resolve().parent
EXAMPLE={'description':'08장 전용 가상 학습 자료. 학생 100명의 분류와 제품 1,000개의 검사 예제이며 실제 조사 결과가 아님.','table':{'A_B':18,'A_notB':22,'notA_B':12,'notA_notB':48},'screening':{'total':1000,'errors':20,'true_positive':18,'false_positive':98}}

def build():
 (ROOT/'probability-example.json').write_text(json.dumps(EXAMPLE,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 def t(x,y,s,extra=''):return f'<text x="{x}" y="{y}" {extra}>{escape(str(s))}</text>'
 def line(x,y,xx,yy):return f'<line x1="{x}" y1="{y}" x2="{xx}" y2="{yy}" stroke="#94a3b8"/>'
 def box(x,y,w,h,c,extra=''):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{c}" {extra}/>'
 def fig(id,title,b,cap,h):return f'<figure class="learn-chart learn-chart--wide"><svg viewBox="0 0 640 {h}" role="img" aria-labelledby="{id}-title {id}-desc"><title id="{id}-title">{title}</title><desc id="{id}-desc">{cap}</desc>{b}</svg><figcaption class="learn-chart__caption">{cap}</figcaption></figure>'
 b=t(24,27,'100명을 겹치지 않는 네 묶음으로 나눕니다')
 for i,(key,n,c,label) in enumerate([('A_B',18,'#2563eb','A와 B 18'),('A_notB',22,'#93c5fd','A만 22'),('notA_B',12,'#f59e0b','B만 12'),('notA_notB',48,'#cbd5e1','둘 다 아님 48')]):
  start=sum(list(EXAMPLE['table'].values())[:i])
  for j in range(start,start+n):b+=box(40+(j%10)*26,55+(j//10)*26,22,22,c,f'data-cell="{key}"')
  b+=box(335,70+i*58,18,18,c)+t(365,85+i*58,label)
 b+=t(24,340,'한 칸 = 1명 / A: 독서 동아리, B: 운동 동아리')
 f1=fig('events','사건의 교집합과 합집합',b,'그림 1. 가상 학생 100명. 독서 동아리 A는 40명, 운동 동아리 B는 30명이며 둘 다 참여한 학생은 18명입니다. 칸의 위치는 크기나 순위를 나타내지 않습니다.',365)
 b=t(24,28,'조건이 바뀌면 분모가 바뀝니다')
 for i,(label,num,den) in enumerate([('P(A)',40,100),('P(A|B)',18,30),('P(B|A)',18,40)]):
  y=75+i*78;v=num/den;b+=t(24,y+18,label)+box(160,y,340,26,'#e2e8f0')+box(160,y,340*v,26,'#2563eb',f'data-numerator="{num}" data-denominator="{den}"')+t(510,y+19,f'{v:.0%}')+t(160,y+49,f'{num} / {den}명')
 b+=t(24,334,'各 막대의 전체 길이 = 해당 분모의 100%'.replace('各','각'))
 f2=fig('conditioning','조건부확률의 분모',b,'그림 2. 전체 중 독서 동아리는 40%, 운동 동아리 중 독서는 60%, 독서 동아리 중 운동은 45%입니다. 같은 18명도 분모에 따라 다른 비율이 됩니다.',361)
 b=t(24,28,'가지에서는 곱하고, 서로 겹치지 않는 경로는 더합니다')
 for x,y,xx,yy in [(60,175,250,100),(60,175,250,265),(285,100,490,65),(285,100,490,150),(285,265,490,230),(285,265,490,315)]:b+=line(x,y,xx,yy)
 for x,y,s in [(24,160,'전체'),(105,100,'P(A)=0.40'),(95,270,'P(Aᶜ)=0.60'),(225,83,'A'),(222,290,'Aᶜ'),(330,59,'P(B|A)=0.45'),(310,155,'P(Bᶜ|A)=0.55'),(320,215,'P(B|Aᶜ)=0.20'),(310,340,'P(Bᶜ|Aᶜ)=0.80'),(505,70,'B: 0.18'),(505,155,'Bᶜ: 0.22'),(505,235,'B: 0.12'),(505,320,'Bᶜ: 0.48')]:b+=t(x,y,s)
 b+=t(24,383,'P(B) = 0.40×0.45 + 0.60×0.20 = 0.30')
 f3=fig('tree','곱셈법칙과 전확률',b,'그림 3. 가상 학생 100명의 분류를 확률나무로 표현했습니다. 끝의 값은 전체에 대한 결합확률이며 합계는 1입니다. 나무의 선 길이는 확률 크기를 뜻하지 않습니다.',410)
 d=EXAMPLE['screening'];b=t(24,28,'검사가 잘 찾아내도 표시된 제품이 모두 결함품은 아닙니다')
 for i,(label,total,flag,color) in enumerate([('실제 결함',20,18,'#2563eb'),('결함 없음',980,98,'#f59e0b')]):
  y=80+i*100;b+=t(24,y,label)+t(24,y+26,f'{total}건 중 {flag}건 표시')+box(240,y-15,flag*2.6,28,color,f'data-flagged="{flag}"')+t(250+flag*2.6,y+5,f'{flag}건')
 b+=t(24,289,'표시된 116건 = 실제 결함 18건 + 결함 없는 98건')+t(24,324,'P(결함 | 표시) = 18 / 116 ≈ 15.52%')
 f4=fig('base-rate','기초 비율과 베이즈 정리',b,'그림 4. 가상 제품 1,000개의 검사 예제입니다. 결함 비율 2%, 결함 탐지율 90%, 오탐률 10%를 가정했습니다. 막대 길이는 검사에서 표시된 건수에 비례하며 실제 검사 성능을 뜻하지 않습니다.',355)
 parts=[]
 def sec(id,label,title,body):parts.append(f'<section class="learn-chapter__step" id="{id}" data-toc-label="{label}"><p class="learn-chapter__label">{label}</p><h2>{title}</h2>{body}</section>')
 sec('quick-start','서두 · 학습목표','‘무엇 중에서’의 답이 바뀌면 확률도 달라집니다','<p>학교에서 학생 한 명을 뽑았을 때 독서 동아리 학생일 확률과, 운동 동아리 학생 중 한 명을 뽑았을 때 독서 동아리에도 참여할 확률은 같을까요? 두 질문은 비슷해 보이지만 기준으로 삼는 학생들이 다릅니다.</p><p>확률을 읽을 때는 숫자보다 먼저 <strong>어떤 결과를, 무엇을 기준으로 세었는지</strong>를 확인해야 합니다. 특히 조건이 붙으면 분모가 바뀐다는 점이 중요합니다.</p><ul class="learn-objectives"><li><strong>표본공간과 사건</strong>을 정하고 겹치는 경우를 중복 없이 셉니다.</li><li><strong>조건부확률</strong>에서 분모가 바뀌는 이유를 설명하고 독립과 배반을 구별합니다.</li><li>확률나무와 <strong>베이즈 정리</strong>로 조건의 방향을 바꾸는 계산을 이해합니다.</li></ul><p>앞에서 배운 <a href="/learn/stats/population-and-sampling/">모집단과 표본</a>을 떠올리며 읽어 보세요. 이 장은 별도로 만든 학생 100명과 제품 1,000개의 가상 자료를 사용합니다.</p>')
 sec('events','표본공간과 사건','가능한 결과 전체와 관심 있는 결과를 정합니다','<p>주사위를 한 번 던지거나 명단에서 한 명을 뽑는 것처럼 결과가 우연에 따라 정해지는 과정을 <strong>시행</strong>이라고 합니다. 가능한 결과 전체는 <strong>표본공간 Ω</strong>, 그중 관심 있는 결과의 묶음은 <strong>사건</strong>입니다. 주사위에서 짝수가 나오는 사건은 {2, 4, 6}입니다.</p><p>이번 예시에서는 학생 100명의 명단에서 각 학생이 같은 확률로 뽑히도록 한 명을 고릅니다. A는 ‘독서 동아리에 참여’, B는 ‘운동 동아리에 참여’로 정했습니다. 두 동아리에 함께 참여할 수도 있습니다.</p><ul><li><strong>A∩B:</strong> 둘 다 참여한 학생들의 교집합입니다.</li><li><strong>A∪B:</strong> 적어도 하나에 참여한 학생들의 합집합입니다. 둘 다 참여한 경우도 포함합니다.</li><li><strong>Aᶜ:</strong> 독서 동아리에 참여하지 않은 학생들의 여사건입니다.</li></ul>'+f1+'<div class="learn-data learn-data--full"><table><caption>가상 학생 100명의 동아리 참여 · 단위: 명</caption><thead><tr><th scope="col">구분</th><th scope="col">B: 운동 참여</th><th scope="col">Bᶜ: 운동 미참여</th><th scope="col">합계</th></tr></thead><tbody><tr><th scope="row">A: 독서 참여</th><td>18</td><td>22</td><td>40</td></tr><tr><th scope="row">Aᶜ: 독서 미참여</th><td>12</td><td>48</td><td>60</td></tr><tr><th scope="row">합계</th><td>30</td><td>70</td><td>100</td></tr></tbody></table></div><p>모든 학생의 참여 여부를 알고 있다고 가정했습니다. 실제 조사에서 응답이 빠졌다면 어떤 학생을 분모에 포함했는지도 확인해야 합니다. <a href="../probability-example.json">가상 집계값(JSON)</a>에서 수치를 확인할 수 있습니다.</p>')
 sec('rules','확률의 기본 규칙','겹치는 경우를 한 번 빼 줍니다','<p>확률은 0 이상 1 이하이며, 가능한 결과 전체의 확률은 1입니다. 어떤 사건이 일어나지 않을 확률은 1에서 그 사건의 확률을 뺀 값입니다.</p><p><strong>P(Aᶜ)=1−P(A)<br>P(A∪B)=P(A)+P(B)−P(A∩B)</strong></p><p>독서 40명과 운동 30명을 그대로 더하면 두 동아리에 참여한 18명을 두 번 셉니다. 한 번 빼면 적어도 하나에 참여한 학생은 40+30−18=52명입니다. 각 학생이 같은 확률로 뽑히므로 P(A∪B)=52/100=0.52입니다. 둘 다 참여하지 않은 확률은 0.48입니다.</p><p><strong>해당 인원÷전체 인원</strong>으로 바로 구할 수 있는 것은 학생마다 선택확률이 같기 때문입니다. 선택확률이 다르면 해당 결과들의 확률을 더해야 합니다. 조사한 명단의 비율을 더 큰 모집단의 확률로 넓혀 해석하려면 대표성과 표집 방법도 살펴봐야 합니다.</p><p>확률이 0.4라고 해서 10번 뽑으면 반드시 4번 나오는 것은 아닙니다. 같은 조건에서 반복해도 실제 횟수는 달라질 수 있습니다. 모형으로 정한 확률과 한 번 관측한 비율을 구별하세요.</p>')
 sec('conditional','조건부확률','조건에 맞는 사람들만 새 분모로 삼습니다','<p><strong>P(A|B)</strong>는 ‘B가 주어졌을 때 A일 확률’입니다. 세로선 오른쪽 B가 조건입니다. B가 시간상 먼저 일어났다는 뜻은 아닙니다.</p><p><strong>P(A|B)=P(A∩B)÷P(B)</strong>이며 P(B)가 0보다 커야 합니다.</p>'+f2+'<p>운동 동아리 학생 30명만 보면 그중 독서에도 참여한 학생은 18명입니다. 따라서 P(A|B)=18/30=60%입니다. 반대로 독서 동아리 학생 40명 중 운동에도 참여한 비율은 P(B|A)=18/40=45%입니다.</p><p>교집합은 같은 18명이지만 <strong>조건을 뒤집으면 분모가 달라집니다.</strong> P(A|B)와 P(B|A)는 일반적으로 같지 않습니다.</p><p>조건에 해당하는 사람이 한 명도 없다면 이 비율을 계산할 수 없습니다. 이 경우를 0%라고 적어서는 안 됩니다. 또한 동아리 참여 사이의 조건부 비율만으로 한 활동이 다른 활동의 원인이라고 결론 내릴 수는 없습니다.</p>')
 sec('independence','독립과 배반','확률이 바뀌지 않는 것과 함께 일어날 수 없는 것은 다릅니다','<p><strong>독립</strong>은 한 사건을 알게 되어도 다른 사건의 확률이 달라지지 않는 경우입니다. P(B)&gt;0일 때 P(A|B)=P(A)이며, 일반적으로 <strong>P(A∩B)=P(A)P(B)</strong>로 표현합니다.</p><p>학생 명단에서는 P(A)=0.40인데 P(A|B)=0.60입니다. 0.18도 0.40×0.30과 다르므로 이 추출에서 두 동아리 참여 사건은 독립이 아닙니다.</p><p><strong>배반</strong>은 두 사건이 동시에 일어날 수 없는 경우입니다. 주사위를 한 번 던져 1이 나오는 것과 2가 나오는 것은 배반입니다. 두 사건의 확률이 모두 양수라면 배반인 사건들은 독립일 수 없습니다. 하나가 일어났다는 것을 알면 다른 하나의 확률이 0이 되기 때문입니다.</p><p>공정한 동전을 두 번 독립적으로 던지면 둘 다 앞면일 확률은 1/2×1/2=1/4입니다. 반면 명단에서 뽑은 사람을 되돌려 놓지 않고 두 명을 고르면 첫 선택이 다음 명단의 구성에 영향을 줍니다. 독서 동아리 두 명을 뽑을 확률은 (40/100)×(39/99)≈15.76%입니다. 다시 명단에 넣고 독립적으로 뽑을 때의 16%와 다릅니다.</p><p>이 계산은 고정된 가상 명단에 관한 것입니다. 실제 조사에서 비율이 비슷하게 나왔다는 사실만으로 모집단의 독립을 입증할 수는 없습니다.</p>')
 sec('tree','곱셈법칙과 전확률','한 경로에서는 곱하고 나뉜 경로는 더합니다','<p>두 사건이 함께 일어날 확률은 첫 사건의 확률에 그 조건에서 두 번째 사건이 일어날 확률을 곱한 것입니다.</p><p><strong>P(A∩B)=P(A)P(B|A)</strong></p><p>독립일 때만 P(B|A)를 P(B)로 바꿀 수 있습니다. 독립인지 확인하지 않고 두 확률을 바로 곱하지 않도록 주의하세요.</p>'+f3+'<p>운동 동아리 학생은 독서에 참여한 경로와 참여하지 않은 경로로 나눌 수 있습니다. 두 경로는 겹치지 않으므로 더하면 전체 운동 참여 확률이 됩니다.</p><p><strong>P(B)=P(A)P(B|A)+P(Aᶜ)P(B|Aᶜ)</strong></p><p>이것이 전확률법칙입니다. 예시에서는 0.40×0.45+0.60×0.20=0.30입니다. 45%와 20%를 단순 평균한 32.5%가 아니라, 각 집단의 크기인 40%와 60%를 비중으로 반영합니다.</p>')
 sec('bayes','베이즈 정리','조건의 방향을 바꿀 때는 원래 비율도 필요합니다','<p>독서 참여자 중 운동 참여 비율을 안다고 해서 운동 참여자 중 독서 참여 비율도 바로 아는 것은 아닙니다. 조건의 방향을 바꾸려면 각 집단이 전체에서 차지하는 비율도 필요합니다.</p><p>교집합을 두 방향으로 쓰면 P(A)P(B|A)=P(B)P(A|B)입니다. 이를 정리한 것이 <strong>베이즈 정리</strong>입니다.</p><p><strong>P(A|B)=P(B|A)P(A)÷P(B)</strong> (P(B)&gt;0)</p><p>학생 예시에서는 0.45×0.40÷0.30=0.60입니다. 조건을 반영하기 전의 P(A)를 <strong>사전확률</strong>, 조건 B를 반영한 P(A|B)를 <strong>사후확률</strong>이라고 합니다.</p><p>이번에는 제품 1,000개를 검사하는 별도 가상 예시를 보겠습니다. 실제 결함품은 20개입니다. 검사는 그중 18개를 표시하고, 결함이 없는 980개 중에서도 98개를 표시한다고 가정합니다.</p>'+f4+'<p>결함품 중 표시된 비율인 <strong>탐지율 P(표시|결함)</strong>은 18/20=90%입니다. 하지만 표시된 제품 중 실제 결함 비율은 <strong>P(결함|표시)=18/(18+98)≈15.52%</strong>입니다. 조건의 방향이 다릅니다.</p><p>같은 계산을 확률로 쓰면 (0.90×0.02)/(0.90×0.02+0.10×0.98)입니다. 결함이 원래 2%로 드물기 때문에 결함 없는 제품에서 나온 표시도 함께 고려해야 합니다. 오탐률 10%는 ‘결함 없는 제품 중 표시된 비율’이며 ‘표시된 제품 중 결함 없는 비율’과도 다릅니다.</p><details class="learn-more"><summary>우도는 무엇인가요?</summary><div class="learn-more__body"><p>A일 때 관측한 조건 B가 나타날 가능성 P(B|A)를 이 맥락에서 우도라고 부릅니다. 예를 들어 결함품이 검사에 표시될 가능성입니다. 이를 P(A|B)처럼 조건을 뒤집은 확률로 읽으면 안 됩니다.</p></div></details>')
 sec('practice','확인 문제','먼저 어떤 분모를 쓰는지 말해 보세요','<ol class="learn-exercises"><li>독서 또는 운동 동아리에 참여한 학생은 몇 명인가요?<details><summary>답과 해설</summary><p>40+30−18=52명입니다. 두 곳 모두 참여한 18명을 한 번 빼 중복을 없앱니다.</p></details></li><li>‘독서 참여자 중 운동’과 ‘운동 참여자 중 독서’의 비율은 각각 얼마인가요?<details><summary>답과 해설</summary><p>각각 18/40=45%, 18/30=60%입니다. 같은 18명이라도 조건에 따라 분모가 다릅니다.</p></details></li><li>확률이 모두 양수인 두 사건이 배반이면서 독립일 수 있을까요?<details><summary>답과 해설</summary><p>아니요. 교집합 확률은 0인데 두 확률의 곱은 양수이므로 독립 조건과 맞지 않습니다.</p></details></li><li>결함 탐지율이 90%이면 표시된 제품 중 90%가 결함품인가요?<details><summary>답과 해설</summary><p>아니요. 조건의 방향이 반대입니다. 예시에서는 결함의 기초 비율과 오탐을 함께 반영하면 18/116≈15.52%입니다.</p></details></li></ol>')
 sec('macro','CH2 Macro에서 읽기','필터로 달라진 기준 집단을 확인합니다','<p>CH2 Macro에서 지역·기간·유형·면적 같은 필터를 고르면 분석 대상이 달라집니다. 비율을 읽을 때는 무엇을 분모로 삼았는지부터 확인하세요.</p><ul><li><strong>전체 중 해당 유형:</strong> 정한 전체 거래에서 그 유형이 차지하는 비율입니다.</li><li><strong>특정 면적 조건 안의 해당 유형:</strong> 면적 조건에 맞는 거래만 분모로 삼은 비율입니다.</li><li><strong>특정 유형 안의 면적 조건:</strong> 그 유형의 거래만 분모로 삼으므로 바로 앞 비율과 일반적으로 다릅니다.</li></ul><p>결측값이나 제외 조건이 있으면 계산에 실제로 쓰인 건수도 확인해야 합니다. 필터에 해당하는 거래가 없을 때의 비율을 0%와 혼동하지 않도록 주의하세요.</p><p>과거 거래에서 관측한 비율을 미래 거래의 발생 확률이나 개별 물건의 가격 상승 확률로 그대로 바꿔 읽지는 않습니다. 그런 추론에는 자료가 대표하는 범위와 시간 변화에 관한 별도의 모형·검증이 필요합니다. 이 장의 가상 검사 예제도 서비스의 이상치 판정 정확도를 뜻하지 않습니다.</p><p class="learn-macro-cta"><a href="https://macro.ch2data.com/land/">CH2 Macro 토지 통계 열기 →</a></p>')
 sec('recap','결론 · 학습 요약','확률의 숫자와 함께 대상·조건·분모를 읽으세요','<p>확률 계산에서는 무엇을 세고 있는지 분명히 하는 것이 출발점입니다. 다음 내용을 기억해 두세요.</p><ul class="learn-recap-list"><li><strong>사건:</strong> 가능한 결과 전체에서 관심 있는 결과의 묶음입니다. 합집합을 셀 때는 겹치는 부분을 한 번 뺍니다.</li><li><strong>조건부확률:</strong> 조건에 맞는 결과를 새 기준으로 삼습니다. P(A|B)와 P(B|A)의 분모는 다릅니다.</li><li><strong>독립과 배반:</strong> 독립은 조건을 알아도 확률이 달라지지 않는 것, 배반은 동시에 일어날 수 없는 것입니다.</li><li><strong>경로 계산:</strong> 같은 경로에서는 조건부확률을 곱하고 겹치지 않는 경로는 더합니다.</li><li><strong>베이즈 정리:</strong> 조건의 방향을 바꿀 때 원래 사건의 기초 비율과 다른 경로로 조건이 발생할 가능성도 반영합니다.</li></ul><p>다음 <a href="/learn/stats/probability-distributions/">9장 ‘확률변수와 확률분포’</a>에서는 우연한 결과를 숫자로 나타내고 각 값의 확률을 살펴봅니다.</p><details class="learn-more"><summary>참고자료</summary><div class="learn-more__body"><ul><li><a href="https://openstax.org/books/introductory-statistics-2e/pages/3-1-terminology">OpenStax, Introductory Statistics 2e §3.1</a> — 표본공간·사건·조건부확률.</li><li><a href="https://openstax.org/books/introductory-statistics-2e/pages/3-3-two-basic-rules-of-probability">OpenStax §3.3</a> — 확률의 덧셈·곱셈법칙.</li></ul><p class="learn-source-note">참고자료의 기존 확인일: 2026-10-07. 설명과 네 그림은 이 장을 위해 정한 가상 집계값으로 작성했습니다. 실제 조사 결과나 검사 성능이 아닙니다.</p></div></details>')
 p=ROOT/'probability/index.html';p.parent.mkdir(exist_ok=True)
 s=p.read_text(encoding='utf-8') if p.exists() else (ROOT/'iqr-outliers/index.html').read_text(encoding='utf-8')
